import json
from pathlib import Path
from collections import defaultdict

judgment_dir = Path("/root/gated_mfrm_judge_bias/exp003/judgment_data_n17")

# Raw coverage: unique items per judge, NO status/score filtering
# This is "did the judge attempt this item at all"
print("=== Raw coverage (no filtering) ===")
for judge_dir in sorted(judgment_dir.iterdir()):
    if not judge_dir.is_dir():
        continue
    items = set()
    for f in judge_dir.glob("*.jsonl"):
        for line in open(f):
            if line.strip():
                rec = json.loads(line)
                items.add(rec["item_id"])
    print(f"  {judge_dir.name}: {len(items)}/500 = {len(items)/500*100:.1f}%")

# Coverage with status=ok filter only (no score/tie filter)
print("\n=== Coverage (status=ok only) ===")
for judge_dir in sorted(judgment_dir.iterdir()):
    if not judge_dir.is_dir():
        continue
    items = set()
    for f in judge_dir.glob("*.jsonl"):
        for line in open(f):
            if line.strip():
                rec = json.loads(line)
                if rec.get("status") == "ok":
                    items.add(rec["item_id"])
    print(f"  {judge_dir.name}: {len(items)}/500 = {len(items)/500*100:.1f}%")

# Coverage with status=ok AND valid score (non-null, non-empty)
print("\n=== Coverage (status=ok + valid score) ===")
for judge_dir in sorted(judgment_dir.iterdir()):
    if not judge_dir.is_dir():
        continue
    items = set()
    for f in judge_dir.glob("*.jsonl"):
        for line in open(f):
            if line.strip():
                rec = json.loads(line)
                if rec.get("status") == "ok":
                    s = rec.get("score")
                    if s is not None and s != "":
                        items.add(rec["item_id"])
    print(f"  {judge_dir.name}: {len(items)}/500 = {len(items)/500*100:.1f}%")

# Check Gemini: how many records total, how many status!=ok?
print("\n=== Gemini detail ===")
gemini_dir = judgment_dir / "gemini-2.5-pro-proxy"
status_counts = defaultdict(int)
items_by_status = defaultdict(set)
for f in gemini_dir.glob("*.jsonl"):
    for line in open(f):
        if line.strip():
            rec = json.loads(line)
            st = rec.get("status", "missing")
            status_counts[st] += 1
            items_by_status[st].add(rec["item_id"])
print(f"  Status counts: {dict(status_counts)}")
for st, it in items_by_status.items():
    print(f"  Status '{st}': {len(it)} unique items")

# Also check Sonnet
print("\n=== Sonnet detail ===")
sonnet_dir = judgment_dir / "claude-sonnet-4.6-proxy"
status_counts = defaultdict(int)
items_by_status = defaultdict(set)
for f in sonnet_dir.glob("*.jsonl"):
    for line in open(f):
        if line.strip():
            rec = json.loads(line)
            st = rec.get("status", "missing")
            status_counts[st] += 1
            items_by_status[st].add(rec["item_id"])
print(f"  Status counts: {dict(status_counts)}")
for st, it in items_by_status.items():
    print(f"  Status '{st}': {len(it)} unique items")
